input.command:
$root='C:\Users\eric_rash\Desktop\DEV'
$skip='^(\.claude|_tools|_DRIVE|token-dashboard)$|_OLD_merged'
$dirs=@()
$dirs += Get-ChildItem $root -Directory -Force | ?{ $_.Name -notmatch $skip }
foreach($s in 'Football','SpecialRequests'){ if(Test-Path "$root\$s"){ $dirs += Get-ChildItem "$root\$s" -Directory -Force | ?{ $_.Name -notmatch $skip } } }
$extra = '.claude','.claude\skills','.claude\global-memory' | %{ Get-Item "$HOME\$_" -Force -ErrorAction SilentlyContinue }
$rows=foreach($d in @($extra)+$dirs){
  $p=$d.FullName
  if(-not (Test-Path "$p\.git")){ [pscustomobject]@{Repo=$p.Replace("$root\",'');State='not a repo';Dirty='';Ahead='';Last=''}; continue }
  $remote = git -C $p remote get-url origin 2>$null
  $dirty = @(git -C $p status --porcelain 2>$null).Count
  $ahead = git -C $p rev-list --count '@{u}..HEAD' 2>$null
  if(-not $ahead){ $ahead = if($remote){'no upstream'} else {'-'} }
  $last = git -C $p log -1 --format=%cs 2>$null
  [pscustomobject]@{Repo=$p.Replace("$root\",'').Replace("$HOME\",'~\');State=$(if($remote){'remote'}else{'NO REMOTE'});Dirty=$dirty;Ahead=$ahead;Last=$last}
}
"TOTAL: $($rows.Count)"
"CLEAN: " + @($rows | ?{ $_.State -eq 'remote' -and $_.Dirty -eq 0 -and $_.Ahead -eq '0' }).Count
$rows | ?{ -not ($_.State -eq 'remote' -and $_.Dirty -eq 0 -and $_.Ahead -eq '0') } | Sort-Object Last -Descending | Format-Table -AutoSize | Out-String -Width 200

